                }
                if (j < 0 || !Character.isLetterOrDigit(prev)) {
                    inQuote = ch;
                }
            }
            continue;
        }

        if (inQuote != '\0') {
            continue;
        }

        afterNewLine = false;

        if (isSymbol(ch)) {
            allSymbols.add(ch);
            increment(symbols, ch);
